// Compiles spec/<version>/story.schema.json into a standalone validator
// module (src/generated/), so the package validates without running Ajv's
// compiler at runtime. That compiler builds functions with `new Function`,
// which a page with a strict Content-Security-Policy (no 'unsafe-eval')
// refuses -- and embedding the viewer on other people's sites is the point.
// The generated file is committed; the tests fail if it's stale.
import { readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import Ajv2020 from "ajv/dist/2020.js";
import standaloneCode from "ajv/dist/standalone/index.js";

const root = fileURLToPath(new URL("..", import.meta.url));
const schema = JSON.parse(readFileSync(`${root}spec/1.0/story.schema.json`, "utf8"));
const ajv = new Ajv2020({ code: { source: true, esm: true }, allErrors: true, strict: true });
const validate = ajv.compile(schema);
const code = standaloneCode(ajv, validate);
const header = "// GENERATED by scripts/generate-validator.mjs from spec/1.0/story.schema.json -- do not edit.\n// @ts-nocheck\n";
const out = `${root}src/generated/schemaValidator.js`;
const check = process.argv.includes("--check");
const next = header + code + "\n";
if (check) {
  const current = readFileSync(out, "utf8");
  if (current !== next) {
    console.error("src/generated/schemaValidator.js is stale: run npm run generate");
    process.exit(1);
  }
} else {
  writeFileSync(out, next);
  console.log(`wrote ${out}`);
}
